code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[rr][cc] == 3 for rr, cc in ((r-1,c-1),(r-1,c),(r-1,c+1),(r,c-1),(r,c+1),(r+1,c-1),(r+1,c),(r+1,c+1))):
                centers.append((r, c))
    # The long blue separators determine the travel direction.
    col_score = max((sum(grid[r][c] == 2 for r in range(h)) for c in range(w)), default=0)
    row_score = max((sum(grid[r][c] == 2 for c in range(w)) for r in range(h)), default=0)
    horizontal = col_score >= row_score  # vertical separators -> horizontal rays
    for r, c in centers:
        if horizontal:
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1
            # Each separator crossed by the ray blooms into a 3x3 patch.
            for cc in range(w):
                if grid[r][cc] == 2 and abs(cc-c) > 1:
                    for rr in range(max(0,r-1), min(h,r+2)):
                        for ccc in range(max(0,cc-1), min(w,cc+2)):
                            if (rr,ccc) != (r,cc) and out[rr][ccc] == 0:
                                out[rr][ccc] = 1
        else:
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
            for rr in range(h):
                if grid[rr][c] == 2 and abs(rr-r) > 1:
                    for rrr in range(max(0,rr-1), min(h,rr+2)):
                        for cc in range(max(0,c-1), min(w,c+2)):
                            if (rrr,cc) != (rr,c) and out[rrr][cc] == 0:
                                out[rrr][cc] = 1
    return out
'''
